<template>
    <div class="container" v-loading="loading">
        <div class="vote_add_top" @click="return_vote_list_add">
            <i class="el-icon-arrow-left"></i>&nbsp;&nbsp;返回列表
        </div>
        <div class="box-limit">
            <div class="container-box">
                <div class="editbox">
                    <div class="mf_10">
                        <span class="fs_14 title_1">提示标题：</span>
                        <div class="div_1" style="margin-top: 10px">
                            <el-input placeholder="请输入提示标题" v-model="post.title"></el-input>
                        </div>
                    </div>
                    <div class="mf_10" style="display: flex;">
                        <span class="fs_14 title_1">提示内容：</span>
                        <div class="div_1">
                            <rich-text :info.sync="content" />
                        </div>
                    </div>
                    <div class="mf_10">
                        <span class="fs_14 title_1">是否启用：</span>
                        <div class="div_1">
                            <el-radio v-model="post.status" label="0">否</el-radio>
                            <el-radio v-model="post.status" label="1">是</el-radio>
                        </div>
                    </div>

                    <div style="margin-top: 20px">
                        <el-button type="primary" style="width:270px;display: block;margin: auto" @click="finish_vote">提交</el-button>
                    </div>
                </div>


            </div>
        </div>
    </div>
</template>

<script>
    import VueDragResize from 'vue-drag-resize';
    import RichText from '@/components/RichText';
    export default {
        name: 'content',
        components: {
            VueDragResize,
            RichText
        },
        data() {
            return {
                loading: false,
                post:{
                    template_id:0,
                    title:'',
                    content:'',
                    status:0

                },
                content: '',
            }
        },
        created () {
            this.post.template_id = this.$route.query.template_id;
            if (this.post.template_id>0) {
                let param = {};
                param['template_id'] = this.post.template_id;
                this.templateTips(param);
            }
        },
        mounted() {
            console.log('mounted');
            let listEl = document.getElementById('list');
        },
        methods: {

            //返回上一页
            return_vote_list_add: function () {
                this.$router.replace({ path: '/template_list'});
            },

            // 获取详情
            async templateTips(param) {
                let res = await this.$api.templateTips(param);
                if (res) {
                    this.post=res;
                    this.content=res.content;
                    console.log(`templateTips: `, res);
                }
            },

            // 添加
            async addData(param) {
                let res = await this.$api.templateTipsSub(param);
                let _this=this;
                console.log(res)
                if (res) {
                    this.$message({
                        type: 'success',
                        message: '操作成功!'
                    });
                } else if (res.errorMsg) {
                    this.$message({
                        type: 'info',
                        message: res.errorMsg
                    });
                    return false;
                }else{
                    return false;
                }
                _this.$router.replace({ path: '/template_list'});
                return res;
            },

            finish_vote: function(e) {
                this.post.content=this.content;
                if(this.post.status == '1'){
                    if (!this.post.title) {
                        console.log('err：',1);
                        this.$message({
                            message: '请输入标题',
                            type: 'error'
                        });
                        return false;
                    }
                    if (!this.post.content) {
                        this.$message({
                            message: '请输入内容',
                            type: 'error'
                        });
                        return false;
                    }
                }
                let param = {};
                param['template_id'] = this.post.template_id;
                param['title'] = this.post.title;
                param['content'] = this.post.content;
                param['status'] = this.post.status;
                this.addData(param);
            },
        }
    }
</script>

<style scoped>

    .mf_10{
        margin-left: 10px;
        margin-bottom: 20px;
    }
    .fs_14{
        font-size: 14px;
    }
    .title_1{
        width: 80px;
        display: inline-block;
    }
    .div_1{
        width: 90%;
        display: inline-block !important;
    }
    .input_title{
        width: 100%;
        height: 40px;
        border: 1px solid #d4d4d4;
        margin: 10px 0;
    }


    .container {
        padding: 0;
        margin: 0;
        background: #f5f5f5;
        width: 100%;
        height: auto;
        overflow: auto;
    }
    .container .box-limit {
        width: calc(100% - 300px);
    }
    .container .addbtn button {
        margin-top: 5px;
        width: 100%;
    }
    .container .container-box .editbox{
        overflow: auto;
    }
    .container .vote_add_top {
        width: 100%;
        padding: 15px;
        text-align: left;
        font-size: 14px;
        box-shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.1);
        background: #ffffff;
        position: fixed;
        top: 0;
        z-index: 999;
    }
    .container-box {
        width: 950px;
        height: auto;
        overflow: auto;
        display: flex;
        flex-direction: row;
        justify-content: center;
        margin: 0 auto;
        margin-top: 55px;
    }
    .editbox {
        width: 950px;
        height: 630px;
        padding: 0 10px;
        margin-bottom: 20px;
        background: #ffffff;
        display: flex;
        flex-direction: column;
        justify-content: flex-start;
        border: 1px solid rgb(226, 230, 237);
    }

</style>
